\"\"\"Minimal, standard-library-only client for OpenAI's Responses API.

Prompts are sent with "'``store=False`` by default so OpenAI does not retain the
response for later retrieval. The API key is read from the ``OPENAI_API_KEY``
environment variable unless passed explicitly; it is never logged.

Example:
    from openai_client import send_prompt
    print(send_prompt("Say hello in French."))
"""

import json
import os
import sys
import urllib.error
import urllib.request

API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4.1-mini"
DEFAULT_TIMEOUT = 60


class OpenAIError(RuntimeError):
    """Raised when the API returns an error or an unexpected response."""

    def __init__(self, message, status=None, body=None):
        super().__init__(message)
        self.status = status
        self.body = body


def create_response(
    prompt,
    model=DEFAULT_MODEL,
    instructions=None,
    api_key=None,
    store=False,
    timeout=DEFAULT_TIMEOUT,
    **extra,
):
    """Send a text prompt and return the full parsed JSON response."""
    if not isinstance(prompt, str) or not prompt:
        raise ValueError("prompt must be a non-empty string")
    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIError("No API key: set OPENAI_API_KEY or pass api_key")

    payload = {"model": model, "input": prompt, "store": store}
    if instructions:
        payload["instructions"] = instructions
    payload.update(extra)

    request = urllib.request.Request(
        API_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + key,
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            body = response.read().decode("utf-8")
    except urllib.error.HTTPError as error:
        body = error.read().decode("utf-8", errors="replace")
        message = body
        try:
            message = json.loads(body)["error"]["message"]
        except (ValueError, KeyError, TypeError):
            pass
        raise OpenAIError(
            "HTTP {}: {}".format(error.code, message), status=error.code, body=body
        ) from None
    except urllib.error.URLError as error:
        raise OpenAIError("Network error: {}".format(error.reason)) from None

    try:
        return json.loads(body)
    except ValueError:
        raise OpenAIError("Invalid JSON in response", body=body) from None


def extract_text(response):
    """Concatenate all output_text segments from a Responses API result."""
    if isinstance(response.get("output_text"), str):
        return response["output_text"]
    parts = []
    for item in response.get("output", []):
        if item.get("type") != "message":
            continue
        for content in item.get("content", []):
            if content.get("type") == "output_text":
                parts.append(content.get("text", ""))
    return "".join(parts)


def send_prompt(prompt, **kwargs):
    """Send a prompt and return only the model'"'s text output.\"\"\"
    response = create_response(prompt, **kwargs)
    if response.get(\"error\"):
        raise OpenAIError(str(response[\"error\"]), body=response)
    return extract_text(response)


def main(argv=None):
    import argparse

    parser = argparse.ArgumentParser(description=\"Send a private prompt to OpenAI.\")
    parser.add_argument(\"prompt\", nargs=\"?\", help=\"prompt text (default: read stdin)\")
    parser.add_argument(\"-m\", \"--model\", default=DEFAULT_MODEL)
    parser.add_argument(\"-i\", \"--instructions\")
    parser.add_argument(\"--timeout\", type=float, default=DEFAULT_TIMEOUT)
    args = parser.parse_args(argv)

    prompt = args.prompt if args.prompt is not None else sys.stdin.read()
    try:
        print(
            send_prompt(
                prompt,
                model=args.model,
                instructions=args.instructions,
                timeout=args.timeout,
            )
        )
    except (OpenAIError, ValueError) as error:
        print(\"error: {}\".format(error), file=sys.stderr)
        return 1
    return 0


if __name__ == \"__main__\":
    sys.exit(main())
