import openai_client as c
print(c.extract_text({'output':[{'type':'message','content':[{'type':'output_text','text':'hi'}]}]}))
import os; os.environ.pop('OPENAI_API_KEY',None)
try: c.send_prompt('x')
except c.OpenAIError as e: print('ok:',e)
